import{_ as r,l as i,o as e,c as d,v as o,p as n,x as t,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"多面体模型","description":"","frontmatter":{"title":"多面体模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/polyhedral-model.md","filePath":"cs/polyhedral-model.md","lastUpdated":1789023840000}'),c={name:"cs/polyhedral-model.md"};function u(m,a,P,_,E,B){const l=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="多面体模型" tabindex="-1">多面体模型 <a class="header-anchor" href="#多面体模型" aria-label="Permalink to &quot;多面体模型&quot;">​</a></h1><div class="epigraph"><p>静态控制部分的迭代域是多面体，依赖是仿射关系。调度用仿射变换同时表达交换、分块、并行与向量化。</p><footer>—— 据 Feautrier, Some Efficient Solutions to the Affine Scheduling Problem；Bastoul, Code Generation in the Polyhedral Model；Bondhugula 等 Pluto 整理</footer></div><p>上一课<a href="/cs/auto-vectorization">自动向量化</a>在最内层做局部判定。缺口是<strong>统一代数</strong>：SCoP（static control part）里，循环界与下标为仿射，迭代点是 \\(\\mathbb{Z}^n\\) 的多面体。Feautrier 调度、Pluto 自动分块。本课钉模型边界，不把整数规划求解器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写交换/分块/向量化各一套启发式，组合爆炸。多面体：依赖多面体 + 求仿射调度函数，使依赖边时间增加。缺口是<strong>何时程序落进模型</strong>（无 <code>while</code> 未知界、无间接下标），不是 SIMD 掩码细节。</p><p>代码生成：扫描多面体重新吐循环（CLooG 等）。</p><h3 id="多面体不是「所有循环」" tabindex="-1">多面体不是「所有循环」 <a class="header-anchor" href="#多面体不是「所有循环」" aria-label="Permalink to &quot;多面体不是「所有循环」&quot;">​</a></h3><p>链表、<code>while (p)</code>、<code>a[b[i]]</code> 通常出模型。编译器只对检测出的 SCoP 启用。不要声称整个 C 程序都在多面体里。</p><p><span class="marginnote">Feautrier 1990s。Wilde/Bastoul CLooG。Bondhugula Pluto。Polly（LLVM）、Graphite（GCC）。本课不进 polyhedral compilation 的全部 ILP 技巧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽取 SCoP。建依赖。解调度（最小化通信、最大化内层并行）。生成循环。再跑向量化。失败则保持原循环。</p>',11)),(e(),n(p,null,{default:t(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCOP%5B%22%E4%BB%BF%E5%B0%84%20SCoP%22%5D%20--%3E%20DEP%5B%22%E4%BE%9D%E8%B5%96%E5%A4%9A%E9%9D%A2%E4%BD%93%22%5D%0A%20%20DEP%20--%3E%20SCH%5B%22%E4%BB%BF%E5%B0%84%E8%B0%83%E5%BA%A6%22%5D%0A%20%20SCH%20--%3E%20GEN%5B%22%E5%86%8D%E7%94%9F%E6%88%90%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/abstract-interpretation">抽象解释</a>：多面体是精确的迭代集表示，不是区间那么粗，但适用范围窄。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译时间：ILP 可能爆。实用：限维、限语句数。浮点结合与并行归约仍要语言许可。</p><p>不要把多面体当 GPU 自动生成的全部（还要共享内存映射等）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Pluto 目标函数全文。后课默认：仿射嵌套可用多面体统一变换。下一课别名：模型外与模型内都要回答「是否同一位置」。</p><p>也不把线性规划当本课的优化对象（那是算法课）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多面体：迭代域与仿射依赖 + 调度变换。</li><li>只覆盖 SCoP；间接与 while 排除。</li><li>生成后再接向量化与分块目标。</li><li>出处：Feautrier；Bastoul；Bondhugula et al. Pluto。</li></ul>',9))])}const b=r(c,[["render",u]]);export{S as __pageData,b as default};
